	@Test
	void bitmapRankResolvesBoundarySlots() {
		long[] tops = { 2 * LmdbReferenceNodeLocator.PAGE_SLOTS, 0, 0, 0 };
		LmdbReferenceNodeLocator.Builder builder = LmdbReferenceNodeLocator.builder(arena, 1, tops);
		// slots 0, 63, 64, 4095 on page 0 of the URI type
		long[] payloads = { 0, 63, 64, 4095 };
		for (long payload : payloads) {
			long[][] ordinals = emptyPlanes();
			long[][] refs = emptyPlanes();
			ordinals[LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT] = new long[] { 7 };
			refs[LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT] = new long[] { 1000 + payload };
			builder.addNode(ValueIds.T_URI, payload, ordinals, refs);
		}
		LmdbReferenceNodeLocator locator = builder.build();

		for (long payload : payloads) {
			long headerRef = locator.headerRef(ValueIds.T_URI, payload);
			assertThat(headerRef).as("payload %d", payload).isPositive();
			assertThat(locator.findGroupRun(headerRef, LmdbReferenceNodeLocator.PLANE_OUTGOING_EXPLICIT, 7))
					.isEqualTo(1000 + payload);
		}
		// unoccupied slots on the same page are missing nodes
		assertThat(locator.headerRef(ValueIds.T_URI, 1)).isZero();
		assertThat(locator.headerRef(ValueIds.T_URI, 62)).isZero();
		assertThat(locator.headerRef(ValueIds.T_URI, 65)).isZero();
		// an allocated-but-empty page is absent
		assertThat(locator.headerRef(ValueIds.T_URI, LmdbReferenceNodeLocator.PAGE_SLOTS + 1)).isZero();
	}

