			ordinals[LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT] = new long[] { 1 };
			refs[LmdbReferenceNodeLocator.PLANE_INCOMING_EXPLICIT] = new long[] { payload + 1 };
