	@Test
	void cachedPageLookupMatchesUncachedLookupAcrossPagesAndTypes() {
		long[] tops = { 2 * LmdbReferenceNodeLocator.PAGE_SLOTS, LmdbReferenceNodeLocator.PAGE_SLOTS, 0, 0 };
		LmdbReferenceNodeLocator.Builder builder = LmdbReferenceNodeLocator.builder(arena, 1, tops);
		long[] uriPayloads = { 1, 2, LmdbReferenceNodeLocator.PAGE_SLOTS - 1,
				LmdbReferenceNodeLocator.PAGE_SLOTS, LmdbReferenceNodeLocator.PAGE_SLOTS + 7 };
		for (long payload : uriPayloads) {
			builder.addNode(ValueIds.T_URI, payload, emptyPlanes(), emptyPlanes());
		}
		builder.addNode(ValueIds.T_LITERAL, 2, emptyPlanes(), emptyPlanes());
		LmdbReferenceNodeLocator locator = builder.build();
		LmdbReferenceNodeLocator.SearchContext context = new LmdbReferenceNodeLocator.SearchContext();

		for (long payload : uriPayloads) {
			assertThat(locator.headerRef(ValueIds.T_URI, payload, context))
					.isEqualTo(locator.headerRef(ValueIds.T_URI, payload));
		}
		for (long payload : new long[] { LmdbReferenceNodeLocator.PAGE_SLOTS + 7, 2, 1,
				LmdbReferenceNodeLocator.PAGE_SLOTS - 1 }) {
			assertThat(locator.headerRef(ValueIds.T_URI, payload, context))
					.isEqualTo(locator.headerRef(ValueIds.T_URI, payload));
		}
		assertThat(locator.headerRef(ValueIds.T_LITERAL, 2, context))
				.isEqualTo(locator.headerRef(ValueIds.T_LITERAL, 2));
		assertThat(locator.headerRef(ValueIds.T_URI, 3, context)).isZero();
		assertThat(locator.headerRef(ValueIds.T_BNODE, 0, context)).isZero();
	}

	@Test
	void sparsePagesAcrossTypesResolveIndependently() {
		long[] tops = { 3 * LmdbReferenceNodeLocator.PAGE_SLOTS, LmdbReferenceNodeLocator.PAGE_SLOTS,
				LmdbReferenceNodeLocator.PAGE_SLOTS, LmdbReferenceNodeLocator.PAGE_SLOTS };
		LmdbReferenceNodeLocator.Builder builder = LmdbReferenceNodeLocator.builder(arena, 1, tops);

		long[][] uriOrdinals = emptyPlanes();
		long[][] uriRefs = emptyPlanes();
		uriOrdinals[0] = new long[] { 3 };
		uriRefs[0] = new long[] { 111 };
		builder.addNode(ValueIds.T_URI, 2 * LmdbReferenceNodeLocator.PAGE_SLOTS + 17, uriOrdinals, uriRefs);

		long[][] bnodeOrdinals = emptyPlanes();
		long[][] bnodeRefs = emptyPlanes();
		bnodeOrdinals[3] = new long[] { 9 };
		bnodeRefs[3] = new long[] { 222 };
		builder.addNode(ValueIds.T_BNODE, 17, bnodeOrdinals, bnodeRefs);

		LmdbReferenceNodeLocator locator = builder.build();

		long uriHeader = locator.headerRef(ValueIds.T_URI, 2 * LmdbReferenceNodeLocator.PAGE_SLOTS + 17);
		assertThat(locator.findGroupRun(uriHeader, 0, 3)).isEqualTo(111);
		// the same payload under a different type is a different node
		assertThat(locator.headerRef(ValueIds.T_LITERAL, 17)).isZero();
		long bnodeHeader = locator.headerRef(ValueIds.T_BNODE, 17);
		assertThat(locator.findGroupRun(bnodeHeader, 3, 9)).isEqualTo(222);
		// page 0 and 1 of URI never got nodes
		assertThat(locator.headerRef(ValueIds.T_URI, 17)).isZero();
	}

	@Test
	void allFourPlanesResolveSeparatelyWithHundredPredicates() {
		long[] tops = { LmdbReferenceNodeLocator.PAGE_SLOTS, 0, 0, 0 };
		LmdbReferenceNodeLocator.Builder builder = LmdbReferenceNodeLocator.builder(arena, 1, tops);
		long[][] ordinals = new long[4][];
		long[][] refs = new long[4][];
		for (int plane = 0; plane < 4; plane++) {
			ordinals[plane] = new long[100];
			refs[plane] = new long[100];
			for (int p = 0; p < 100; p++) {
				ordinals[plane][p] = p;
				refs[plane][p] = (plane + 1) * 1000L + p;
			}
		}
		builder.addNode(ValueIds.T_URI, 5, ordinals, refs);
		LmdbReferenceNodeLocator locator = builder.build();

		long headerRef = locator.headerRef(ValueIds.T_URI, 5);
		for (int plane = 0; plane < 4; plane++) {
			assertThat(locator.planeGroupCount(headerRef, plane)).isEqualTo(100);
			for (int p = 0; p < 100; p += 13) {
				assertThat(locator.findGroupRun(headerRef, plane, p)).isEqualTo((plane + 1) * 1000L + p);
			}
			// missing group within an existing node
			assertThat(locator.findGroupRun(headerRef, plane, 100)).isEqualTo(-1);
		}

		long[] entry = new long[2];
		locator.planeEntry(headerRef, 2, 42, entry);
		assertThat(entry[0]).isEqualTo(42);
		assertThat(entry[1]).isEqualTo(3000L + 42);
	}

	@Test
	void gallopingGroupSearchKeepsCallerOwnedPerPlanePositions() throws ReflectiveOperationException {
		long[] tops = { LmdbReferenceNodeLocator.PAGE_SLOTS, 0, 0, 0 };
		LmdbReferenceNodeLocator.Builder builder = LmdbReferenceNodeLocator.builder(arena, 1, tops);
		long[][] firstOrdinals = emptyPlanes();
		long[][] firstRefs = emptyPlanes();
		firstOrdinals[0] = new long[100];
		firstRefs[0] = new long[100];
		for (int i = 0; i < 100; i++) {
			firstOrdinals[0][i] = 2L * i;
			firstRefs[0][i] = 1000L + i;
		}
		firstOrdinals[1] = new long[] { 5, 15, 25 };
		firstRefs[1] = new long[] { 2000, 2001, 2002 };
		builder.addNode(ValueIds.T_URI, 0, firstOrdinals, firstRefs);

		long[][] secondOrdinals = emptyPlanes();
		long[][] secondRefs = emptyPlanes();
		secondOrdinals[0] = new long[] { 4, 40, 80 };
		secondRefs[0] = new long[] { 3000, 3001, 3002 };
		builder.addNode(ValueIds.T_URI, 1, secondOrdinals, secondRefs);
		LmdbReferenceNodeLocator locator = builder.build();
		long firstHeader = locator.headerRef(ValueIds.T_URI, 0);
		long secondHeader = locator.headerRef(ValueIds.T_URI, 1);

		Class<?> contextType = Class.forName(LmdbReferenceNodeLocator.class.getName() + "$SearchContext");
		Constructor<?> constructor = contextType.getDeclaredConstructor();
		Method find = LmdbReferenceNodeLocator.class.getDeclaredMethod("findGroupRun", long.class, int.class,
				long.class, contextType);
		Method position = contextType.getDeclaredMethod("position", int.class);
		Object firstContext = constructor.newInstance();
		Object secondContext = constructor.newInstance();

		assertThat((long) find.invoke(locator, firstHeader, 0, 100L, firstContext)).isEqualTo(1050);
		assertThat((long) find.invoke(locator, firstHeader, 0, 104L, firstContext)).isEqualTo(1052);
		assertThat((long) find.invoke(locator, firstHeader, 0, 98L, firstContext)).isEqualTo(1049);
		assertThat((long) find.invoke(locator, firstHeader, 0, 99L, firstContext)).isEqualTo(-1);
		assertThat((long) position.invoke(firstContext, 0)).isEqualTo(50);

		assertThat((long) find.invoke(locator, firstHeader, 0, 2L, secondContext)).isEqualTo(1001);
		assertThat((long) position.invoke(secondContext, 0)).isEqualTo(1);
		assertThat((long) position.invoke(firstContext, 0)).isEqualTo(50);

		assertThat((long) find.invoke(locator, firstHeader, 1, 25L, firstContext)).isEqualTo(2002);
		assertThat((long) position.invoke(firstContext, 1)).isEqualTo(2);
		assertThat((long) position.invoke(firstContext, 0)).isEqualTo(50);

		assertThat((long) find.invoke(locator, firstHeader, 0, 199L, firstContext)).isEqualTo(-1);
		assertThat((long) position.invoke(firstContext, 0)).isEqualTo(100);
		assertThat((long) find.invoke(locator, secondHeader, 0, 40L, firstContext)).isEqualTo(3001);
		assertThat((long) position.invoke(firstContext, 0)).isEqualTo(1);
		assertThat((long) find.invoke(locator, firstHeader, 0, 196L, firstContext)).isEqualTo(1098);
		assertThat((long) find.invoke(locator, firstHeader, 0, 4L, firstContext)).isEqualTo(1002);
		assertThat((long) find.invoke(locator, secondHeader, 1, 15L, firstContext)).isEqualTo(-1);
		assertThat((long) position.invoke(firstContext, 1)).isZero();

		assertThat((long) position.invoke(secondContext, 0)).isEqualTo(1);
	}

